Here is the modified C++ program to calculate and print the average value of the array:

```cpp
#include <iostream>
#include <numeric> // For std::accumulate
#include <vector>

int main() {
    int array[4] = {2, 3, 5, 7};
    int size = 4;

    // Calculate the sum of the array elements
    int sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += array[i];
    }

    // Calculate the average
    double average = static_cast<double>(sum) / size;

    // Print the result
    std::cout << "The average value is: " << average << std::endl;

    return 0;
}
```

Alternatively, using `std::accumulate` from the `<numeric>` header:

```cpp
#include <iostream>
#include <numeric>

int main() {
    int array[4] = {2, 3, 5, 7};
    int size = 4;

    int sum = std::accumulate(std::begin(array), std::end(array), 0);
    double average = static_cast<double>(sum) / size;

    std::cout << "The average value is: " << average << std::endl;

    return 0;
}
```

